import {visibleCompletionSources} from './completion-display-text.mjs';
import {completionReviewPanel} from './thesis-completion-review.mjs';
import {simulationPanelHTML,simulationPending} from './thesis-simulation-client.mjs';
import {supplementCheckPanel} from './supplement-check-panel.mjs';
import {thesisCompletionNeeds,safeCompletionIssues} from './thesis-completion-model.mjs';
import {thesisCoverFields,thesisManualBackMatter} from './thesis-delivery.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const referenceTypes=[['','未指定'],['preprint','预印本'],['journal','期刊文章'],['conference','会议论文'],['book','专著'],['thesis','学位论文'],['report','报告'],['webpage','网页']];
const referenceExtras={documentType:100,url:2000,journal:500,publisher:500,publicationPlace:200,publicationSource:500,volume:100,issue:100,pages:100};
const validReferenceURL=value=>{if(!String(value||'').trim())return true;try{const url=new URL(value);return ['http:','https:'].includes(url.protocol)&&!url.username&&!url.password;}catch{return false;}};
export function createCompletionDraft(){return {open:false,dirty:false,supplement:'',acknowledgements:'',metadata:{},materials:[],references:[],referenceFragments:[],referenceTexts:[],referenceMetadataUpdates:[],referenceMetadataUpdate:{referenceId:'',documentType:'',url:''},referenceFragment:{referenceId:'',text:''},reference:{title:'',authors:'',year:'',doi:'',text:''},issues:[],messages:[],quote:null,requestKey:null,recheckRunId:null,simulationRunIds:[],simulationJob:null};}
export function completionPayload(draft,version){return {version,clientKey:draft.requestKey,supplement:draft.supplement,acknowledgements:draft.acknowledgements,metadata:draft.metadata,materials:draft.materials.map(({name,text})=>({name,text})),references:draft.references,...(draft.referenceFragments?.length?{referenceFragments:draft.referenceFragments}:{}),...(draft.referenceTexts?.length?{referenceTexts:draft.referenceTexts}:{}),...(draft.referenceMetadataUpdates?.length?{referenceMetadataUpdates:draft.referenceMetadataUpdates}:{}),...(draft.simulationRunIds?.length?{simulationRunIds:draft.simulationRunIds}:{})};}
export function completionDraftRecord(draft){const {quote,...record}=draft;return {...record,messages:[],issues:safeCompletionIssues(draft.issues)};}
export function restoreCompletionDraft(value){
 if(!value||typeof value!=='object'||typeof value.supplement!=='string'||value.supplement.length>50000||typeof value.acknowledgements!=='string'||value.acknowledgements.length>5000||!Array.isArray(value.materials)||value.materials.length>10||value.materials.some(row=>typeof row.name!=='string'||row.name.length>240||typeof row.text!=='string'||row.text.length>50000)||!Array.isArray(value.references)||value.references.length>30)throw Error('终稿补充草稿无效，请重新选择资料。');
 if(value.referenceFragments!==undefined&&(!Array.isArray(value.referenceFragments)||value.referenceFragments.length>10||value.referenceFragments.some(row=>typeof row?.referenceId!=='string'||row.referenceId.length>150||typeof row.text!=='string'||row.text.length>50000)))throw Error('文献补充片段无效');
 if(value.referenceTexts!==undefined&&(!Array.isArray(value.referenceTexts)||value.referenceTexts.length>10||value.referenceTexts.some(row=>typeof row?.referenceId!=='string'||row.referenceId.length>150||typeof row.text!=='string'||row.text.length>50000)))throw Error('文献原文或摘要无效');
 const validUpdate=row=>row&&typeof row.referenceId==='string'&&row.referenceId.length<=150&&typeof row.documentType==='string'&&row.documentType.length<=100&&typeof row.url==='string'&&row.url.length<=2000;
 if(value.referenceMetadataUpdates!==undefined&&(!Array.isArray(value.referenceMetadataUpdates)||value.referenceMetadataUpdates.length>30||value.referenceMetadataUpdates.some(row=>!validUpdate(row))))throw Error('文献题录草稿无效');
 if(value.referenceMetadataUpdate!==undefined&&!validUpdate(value.referenceMetadataUpdate))throw Error('文献题录草稿无效');
 if(value.referenceFragment!==undefined&&(!value.referenceFragment||typeof value.referenceFragment.referenceId!=='string'||value.referenceFragment.referenceId.length>150||typeof value.referenceFragment.text!=='string'||value.referenceFragment.text.length>50000))throw Error('文献补充片段无效');
 if(value.simulationRunIds!==undefined&&(!Array.isArray(value.simulationRunIds)||value.simulationRunIds.length>3||value.simulationRunIds.some(id=>typeof id!=='string'||id.length>100)))throw Error('模拟资料来源无效');
 if(value.simulationJob!==undefined&&value.simulationJob!==null){const job=value.simulationJob;if(typeof job!=='object'||typeof job.thesisId!=='string'||job.thesisId.length>100||typeof job.clientKey!=='string'||job.clientKey.length>100||!Number.isSafeInteger(job.version)||!['submitting','recovering','queued','running','completed','failed','cancelled'].includes(job.status)||job.jobId!==null&&typeof job.jobId!=='string'||String(job.text||'').length>40000)throw Error('模拟任务草稿无效');}
 const draft={...createCompletionDraft(),...value,quote:null,issues:safeCompletionIssues(value.issues)};if(!draft.metadata||Object.entries(draft.metadata).some(([key,text])=>!Object.hasOwn(thesisCoverFields,key)||typeof text!=='string'||text.length>200))throw Error('终稿封面草稿无效');for(const reference of [...draft.references,draft.reference])if(!reference||['title','authors','year','doi','text'].some(key=>typeof reference[key]!=='string'||reference[key].length>(key==='text'?50000:500))||Object.entries(referenceExtras).some(([key,max])=>reference[key]!==undefined&&(typeof reference[key]!=='string'||reference[key].length>max)))throw Error('终稿文献草稿无效');return draft;
}
export function setCompletionIssues(draft,{report,formatting,additional=[]}={}){draft.open=true;draft.quote=null;draft.issues=safeCompletionIssues((report?.submission?.issues||[]).map(row=>row.code));const automatic=(report?.submission?.issues||[]).some(row=>/^(?:abstract_|keywords_|english_title|incomplete_manuscript|table_|raw_formula|duplicate_)/.test(row.code));draft.messages=[...new Set([...(report?.submission?.issues||[]).filter(row=>!/^(?:abstract_|keywords_|english_title|table_|raw_formula|duplicate_)/.test(row.code)).map(row=>row.code==='unresolved_placeholders'?'请按下方章节提示补充缺少的真实资料，系统会更新对应正文。':row.message),...(automatic?['系统将依据补齐后的正文整理摘要、关键词、英文题目及可自动处理的格式问题。']:[]),...(formatting?.unresolved||[]).map(row=>row.message),...additional].filter(value=>typeof value==='string'))].slice(0,40);}
function completionJob(job,completionRunId){
 if(job?.purpose==='draft')return false;
 return job?.purpose==='completion'||['completion','recheck'].includes(job?.operation)||!job?.operation&&job?.id&&job.id===completionRunId;
}
export function draftGenerationActive(item,completionRunId=null){return ['queued','running','cancelling'].includes(item?.job?.status)&&!completionJob(item.job,completionRunId);}
export function completionProgressText(item,busy=false,{preparing=false,completionRunId=null}={}){
 const job=item?.job,active=['queued','running','cancelling'].includes(job?.status),completion=completionJob(job,completionRunId);
 if(draftGenerationActive(item,completionRunId))return '';
 if(!active||!completion)return busy&&preparing?'正在保存资料并准备检查，请稍候…':'';
 if(job.operation==='recheck')return job.status==='cancelling'?'正在停止检查，已保存的正文和资料会保留…':job.status==='queued'?'正在准备重新检查…':'正在检查已保存的正文和资料…';
 if(job.status==='cancelling')return '正在停止自动完善，已完成内容会保留…';
 if(job.stage==='reviewing_draft')return '正在审查初稿，识别缺项与需要完善的内容…';
 if(job.status==='queued')return '资料已保存，正在排队检查与完善…';
 return job.stage==='checking_supplements'?'正在检查补充资料完整性，请稍候…':'正在自动补齐正文并检查，完成后请确认补充结果…';
}
export function completionPrepareText(item,draft){return draft.dirty?'保存材料并自动补齐':item?.completionReview?.basisChanged?'使用已补充资料完善正文':item?.quality?.supplementCheck?.status==='unavailable'?'继续完善并重新检查':'AI自动补充并检查';}
export function templateReferenceRequirementsHTML(template){
 if(!template)return '';
 if(template.status!=='ready')return '<p class="thesis-template-requirements" role="note">学校模板暂不可用，终稿导出前请重新选择模板。</p>';
 const rules=template.profile?.submission;
 if(!rules||typeof rules!=='object'||Array.isArray(rules))return '<p class="thesis-template-requirements" role="note">学校模板的文献数量要求待识别；导出时会重新读取模板，请提前核对学校要求。</p>';
 const min=rules.minimumReferences,foreign=rules.minimumForeignReferences;
 const valid=n=>Number.isSafeInteger(n)&&n>0&&n<=99;
 const parts=[...(valid(min)?[`文献至少 ${min} 条`]:[]),...(valid(foreign)?[`外文文献至少 ${foreign} 篇`]:[])];
 return `<p class="thesis-template-requirements" role="note">${parts.length?`学校模板识别到：${parts.join('；')}。请补充真实文献并核对正文引用。`:'未从学校模板识别到明确的文献数量要求，请按学校规范核对。'}</p>`;
}
function referenceMetadataEditorHTML(item,draft,disabled){
 const references=(item.snapshot?.references||[]).filter(row=>row.confirmed===true);if(!references.length)return '';
 const edit=draft.referenceMetadataUpdate||{referenceId:'',documentType:'',url:''};
 return `<details data-optional-fields open><summary>补充已有文献的题录信息</summary><p>选择已有文献，按实际来源填写类型和网址；保存后保留原文献与正文引用。信息由作者提供，仍需核对。</p><label>选择已有文献<select data-completion-metadata-reference ${disabled}><option value="">请选择文献</option>${references.map(row=>`<option value="${esc(row.id)}" ${edit.referenceId===row.id?'selected':''}>${esc(row.title)}</option>`).join('')}</select></label><div class="creation-row"><label>文献类型<select data-completion-metadata-type ${disabled}>${referenceTypes.map(([value,label])=>`<option value="${value}" ${edit.documentType===value?'selected':''}>${label}</option>`).join('')}</select></label><label>文献网址（可选）<input type="url" maxlength="2000" data-completion-metadata-url value="${esc(edit.url)}" ${disabled}></label></div><button type="button" class="btn secondary" data-completion-add-metadata ${disabled}>保存此项到补充清单</button>${draft.referenceMetadataUpdates?.length?`<ul>${draft.referenceMetadataUpdates.map((row,index)=>`<li>${esc(references.find(ref=>ref.id===row.referenceId)?.title||'已有文献')} · 待保存 <button type="button" data-completion-remove-metadata="${index}" ${disabled}>移除</button></li>`).join('')}</ul>`:''}</details>`;
}
export function completionPanelHTML(item,draft,{busy=false,preparing=false,costText=()=>'',showCover=true,embedded=false,guided=false,showReview=true}={}){
 if(draftGenerationActive(item,draft.recheckRunId))return '<section class="thesis-completion-panel is-embedded" data-thesis-completion><div data-completion-awaiting-draft role="note"><strong>初稿生成中</strong><p>初稿完成后，可在这里补充资料并完善终稿。</p></div></section>';
 const tag=embedded?'section':'details',wait=completionProgressText(item,busy,{preparing,completionRunId:draft.recheckRunId});
 const pendingApplication=item.completionReview?.basisChanged===true||item.quality?.supplementCheck?.status==='unavailable';
 const needs=thesisCompletionNeeds(item),ack=needs.chapters.some(row=>thesisManualBackMatter(row)),disabled=busy?'disabled':'',values={...item.snapshot?.requirements,...item.profile,...item.exportMetadata,...draft.metadata};
 const canRecheck=item.recheck?.enabled===true&&item.recheck?.eligible===true&&(item.chapters||[]).some(chapter=>String(chapter.text||'').trim());
 const reviewAction=canRecheck?`<div class="thesis-recheck-action"><button type="button" class="btn secondary" data-review-saved ${busy||draft.dirty||simulationPending(draft)?'disabled':''}>重新检查已保存正文</button><p>检查已保存的正文和资料，不修改正文；本次不再扣除积分或套餐次数。提交后会核对可用资格。</p></div>`:item.recheck?.reason==='usage_pending'||item.recheck?.reason==='limit_reached'?'<div class="thesis-recheck-action" role="status"><p>本次重新检查暂无法继续，请联系平台客服处理。已保存的正文与资料保留，本次未额外扣费。</p><p>如只需继续本次检查，请先联系支持；“AI 审查并自动补齐”是新的处理操作，确认费用后可能再次收费。</p><a href="#help">联系支持</a></div>':'';
 const primaryAction=`<div class="thesis-action-row${guided?' thesis-completion-main-action':''}"><button type="button" class="btn primary" data-completion-prepare ${guided?'data-completion-guided':''} ${draft.quote?'hidden':''} ${disabled||simulationPending(draft)?'disabled':''}>${guided?'AI 审查并自动补齐':completionPrepareText(item,draft)}</button></div>`;
 return `<${tag} class="thesis-completion-panel${embedded?' is-embedded':''}" data-thesis-completion ${embedded?'':'data-optional-fields open'}>${embedded?'':'<summary>自动补齐并确认终稿</summary>'}<div>${wait&&(!guided||!['queued','running','cancelling'].includes(item.job?.status))?`<section class="document-export-progress" data-completion-progress data-state="running" role="status" aria-live="polite"><div class="document-export-progress-heading"><span class="document-export-spinner" aria-hidden="true"></span><strong data-completion-progress-title>${esc(wait)}</strong></div><div class="document-export-track" role="progressbar" aria-label="资料检查与完善正在进行"><span></span></div><p>已保存的资料会继续使用，无需重复提交。完成后展示补充结果，确认后进入终稿编排。</p></section>`:''}${guided&&!['needs_materials','unavailable'].includes(item.quality?.supplementCheck?.status)?'':supplementCheckPanel(item.quality?.supplementCheck,{stale:item.quality?.stale||draft.dirty})}<section class="thesis-auto-completion-intro" aria-label="AI自动补充缺失内容"><h4>${guided?'AI审查与自动补齐':'AI自动补充缺失内容'}</h4>${guided?'<p>自动检查初稿的章节、摘要、论证、引文与图表说明，依据已有资料补齐内容并复检。完成后统一核对；确需本人提供的事实会单独列出。</p>':'<p>根据论文检查出的缺项，自动补写有依据的内容、整理引用，并直接修正表达后复检。完成后确认修改结果即可。</p><p>已有研究资料和文献会继续使用；本人身份和未提供的真实记录需由你确认，仿真数据保留模拟说明。</p>'}</section>${guided?templateReferenceRequirementsHTML(item.exportTemplate):''}${guided?primaryAction:''}${reviewAction}${draft.messages.length?`<ul class="thesis-completion-requests" aria-label="本次终稿检查缺项">${draft.messages.map(message=>`<li>${esc(visibleCompletionSources(message,item.snapshot?.references))}</li>`).join('')}</ul>`:''}${needs.chapters.length?`<div class="thesis-completion-requests" tabindex="0" role="region" aria-label="${pendingApplication?'正文待更新内容':'需要补充的研究资料'}">${pendingApplication?'<p>以下是旧正文中的待处理位置，系统将结合新资料逐章更新，并重新判断仍需补充的事实。</p>':''}${needs.chapters.map(chapter=>`<article><b>${esc(chapter.title)}</b><ul>${chapter.requests.map(text=>`<li>${esc(visibleCompletionSources(text,item.snapshot?.references))}</li>`).join('')}${chapter.needsTableTitles?'<li>表格名称与编号由系统在完善正文时整理。</li>':''}</ul></article>`).join('')}</div>`:''}<label>研究资料与实际结果${guided?'（按需补充）':''}<textarea data-completion-field="supplement" maxlength="50000" rows="5" placeholder="已有事实、数据或学校要求可在这里补充，系统会使用它们自动完善正文。" ${disabled}>${esc(draft.supplement)}</textarea></label><div class="thesis-action-row"><label class="btn secondary">上传补充材料<input data-completion-file type="file" accept=".txt,.docx,.pdf" hidden ${disabled}></label><button type="button" class="btn secondary" data-completion-stored ${disabled}>从文件管理选择</button><select data-completion-purpose aria-label="附件用途" ${disabled}><option value="material">研究资料</option><option value="reference">文献原文</option></select></div><p data-completion-import-status role="status"></p>${draft.materials.length?`<ul>${draft.materials.map((row,index)=>`<li>${esc(row.name)} <button type="button" data-completion-remove-material="${index}" ${disabled}>移除</button></li>`).join('')}</ul>`:''}${referenceMetadataEditorHTML(item,draft,disabled)}${(item.snapshot?.references||[]).some(row=>row.confirmed)?`<details data-optional-fields open><summary>为已有文献补充正文片段</summary><p>请提供所选文献的原文或摘要。系统按作者提供的内容核对引用，不能独立核验其出处，也不视为全文。已有正文不会被覆盖。</p><label>选择文献<select data-completion-fragment="referenceId" ${disabled}><option value="">请选择文献</option>${item.snapshot.references.filter(row=>row.confirmed).map(row=>`<option value="${esc(row.id)}" ${draft.referenceFragment?.referenceId===row.id?'selected':''}>${esc(row.title)} · ${esc(row.authors||'作者未填写')} ${esc(row.year||'')}</option>`).join('')}</select></label><label>已核对的正文或摘要片段<textarea data-completion-fragment="text" maxlength="50000" rows="4" ${disabled}>${esc(draft.referenceFragment?.text||'')}</textarea></label><p>新增片段单独保存，保留已有正文；片段不一定连续，出处由作者提供，尚未独立核验。</p><button type="button" class="btn secondary" data-completion-add-reference-text ${disabled}>关联文献片段</button><button type="button" class="btn secondary" data-completion-add-fragment ${disabled}>仅作为独立补充片段</button>${draft.referenceTexts?.length?`<ul>${draft.referenceTexts.map((row,index)=>`<li>${esc(item.snapshot.references.find(ref=>ref.id===row.referenceId)?.title||'已有文献')} · 用户提供，出处未独立核验 <button type="button" data-completion-remove-reference-text="${index}" ${disabled}>移除</button></li>`).join('')}</ul>`:''}${draft.referenceFragments?.length?`<ul>${draft.referenceFragments.map((row,index)=>`<li>${esc(item.snapshot.references.find(ref=>ref.id===row.referenceId)?.title||'已有文献')} <button type="button" data-completion-remove-fragment="${index}" ${disabled}>移除</button></li>`).join('')}</ul>`:''}</details>`:''}<details data-optional-fields open><summary>${guided?'新增文献依据（按需补充）':'补充文献依据'}</summary><p>${guided?'已保存的文献继续使用，无需重复填写。':''}提供真实题录与可引用正文，系统根据内容建立引用。</p><div class="creation-row"><label>文献题名<input data-completion-reference="title" maxlength="500" value="${esc(draft.reference.title)}" ${disabled}></label><label>作者<input data-completion-reference="authors" maxlength="500" value="${esc(draft.reference.authors)}" ${disabled}></label></div><div class="creation-row"><label>年份<input data-completion-reference="year" maxlength="20" value="${esc(draft.reference.year)}" ${disabled}></label><label>DOI（可选）<input data-completion-reference="doi" maxlength="500" value="${esc(draft.reference.doi)}" ${disabled}></label></div><div class="creation-row"><label>文献类型（按实际选择）<select data-completion-reference="documentType" ${disabled}>${referenceTypes.map(([value,label])=>`<option value="${value}" ${draft.reference.documentType===value?'selected':''}>${label}</option>`).join('')}</select></label><label>文献网址（可选）<input data-completion-reference="url" type="url" maxlength="2000" value="${esc(draft.reference.url||'')}" placeholder="https://..." ${disabled}></label></div><div class="creation-row"><label>期刊名称（可选）<input data-completion-reference="journal" maxlength="500" value="${esc(draft.reference.journal||'')}" ${disabled}></label><label>会议或出版来源（可选）<input data-completion-reference="publicationSource" maxlength="500" value="${esc(draft.reference.publicationSource||'')}" ${disabled}></label></div><div class="creation-row"><label>出版社（可选）<input data-completion-reference="publisher" maxlength="500" value="${esc(draft.reference.publisher||'')}" ${disabled}></label><label>出版地（可选）<input data-completion-reference="publicationPlace" maxlength="200" value="${esc(draft.reference.publicationPlace||'')}" ${disabled}></label></div><div class="creation-row"><label>卷（可选）<input data-completion-reference="volume" maxlength="100" value="${esc(draft.reference.volume||'')}" ${disabled}></label><label>期（可选）<input data-completion-reference="issue" maxlength="100" value="${esc(draft.reference.issue||'')}" ${disabled}></label><label>页码（可选）<input data-completion-reference="pages" maxlength="100" value="${esc(draft.reference.pages||'')}" ${disabled}></label></div><p>请按实际文献填写类型和出版信息；未知的内容留空，导出前核对完整题录。</p><label>可引用的文献正文或已核对摘要<textarea data-completion-reference="text" maxlength="50000" rows="4" ${disabled}>${esc(draft.reference.text)}</textarea></label><button type="button" class="btn secondary" data-completion-add-reference ${disabled}>加入这篇文献</button>${draft.references.length?`<ul>${draft.references.map((row,index)=>`<li>${esc(row.title)} <button type="button" data-completion-remove-reference="${index}" ${disabled}>移除</button></li>`).join('')}</ul>`:''}</details>${ack?`<label>致谢事实<textarea data-completion-field="acknowledgements" maxlength="5000" rows="3" placeholder="填写希望感谢的人或机构及实际帮助，系统据此整理致谢，不虚构关系和资助。" ${disabled}>${esc(draft.acknowledgements)}</textarea></label>`:''}${showCover?`<details data-optional-fields open><summary>补充封面信息</summary><div class="thesis-cover-grid">${Object.entries(thesisCoverFields).map(([key,label])=>`<label>${label}<input data-completion-cover="${key}" maxlength="200" value="${esc(values[key]||'')}" ${disabled}></label>`).join('')}</div></details>`:''}<div data-thesis-simulation-host>${simulationPanelHTML(draft,{disabled:busy,recovery:item.simulationRecovery,allowGenerate:!guided})}</div><p>保存资料和重新排版不扣写作积分。自动完善和检查完成且有可用修改后按确认方案结算；仍需核对的研究事实会列出，后续再次自动完善需重新确认费用。处理失败或未形成可用修改时不扣费。</p>${draft.quote?`<section class="thesis-completion-quote"><h4>本次自动完善</h4><p>涉及章节：${draft.quote.completion.chapterTitles.map(esc).join('、')}。</p><p>${esc(costText(draft.quote))}</p><p>完成后自动重新检查终稿；仍缺真实资料时继续提示，保留原有版本。</p><button type="button" class="btn primary" data-completion-start ${disabled}>确认费用，自动完善并检查终稿</button></section>`:''}${showReview?completionReviewPanel(item.completionReview,{busy,dirty:draft.dirty,thesisId:item.id}):''}${guided?'':primaryAction}<p data-completion-status role="status"></p></div></${tag}>`;
}
export function updateCompletionPanelState(root,draft,{busy=false,item}={}){
 if(!root)return;
 const prepare=root.querySelector('[data-completion-prepare]');
 if(prepare){prepare.disabled=busy||simulationPending(draft);prepare.textContent=prepare.hasAttribute('data-completion-guided')?'AI 审查并自动补齐':completionPrepareText(item,draft);prepare.hidden=!!draft.quote;}
 const review=root.querySelector('[data-review-saved]');if(review)review.disabled=busy||draft.dirty||simulationPending(draft);
 if(!draft.quote)root.querySelector('.thesis-completion-quote')?.remove();
 if(draft.dirty){const state=root.querySelector('.supplement-check-panel header [role="status"]');if(state)state.textContent='内容或资料已更新，需要重新检查';}
}
export function bindCompletionPanel(root,draft,{item,changed,render,prepare,start,recheck,reviewSaved,confirm,viewChapter,importFile,busy=()=>false}={}){
 if(!root)return;const change=()=>{draft.dirty=true;draft.quote=null;draft.requestKey=null;changed?.();const quote=root.querySelector('.thesis-completion-quote');quote?.remove();};
 if(root.tagName==='DETAILS')root.addEventListener('toggle',()=>{draft.open=root.open;});
 root.querySelectorAll('[data-completion-field]').forEach(input=>input.addEventListener('input',()=>{draft[input.dataset.completionField]=input.value;change();}));
 root.querySelectorAll('[data-completion-cover]').forEach(input=>input.addEventListener('input',()=>{draft.metadata[input.dataset.completionCover]=input.value;change();}));
 root.querySelectorAll('[data-completion-reference]').forEach(input=>input.addEventListener(input.tagName==='SELECT'?'change':'input',()=>{draft.reference[input.dataset.completionReference]=input.value;change();}));
 root.querySelector('[data-completion-metadata-reference]')?.addEventListener('change',event=>{const reference=item?.snapshot?.references?.find(row=>row.id===event.target.value&&row.confirmed===true);draft.referenceMetadataUpdate={referenceId:reference?.id||'',documentType:reference?.documentType||'',url:reference?.url||''};change();render();});
 root.querySelector('[data-completion-metadata-type]')?.addEventListener('change',event=>{draft.referenceMetadataUpdate.documentType=event.target.value;change();});
 root.querySelector('[data-completion-metadata-url]')?.addEventListener('input',event=>{draft.referenceMetadataUpdate.url=event.target.value;change();});
 root.querySelector('[data-completion-add-metadata]')?.addEventListener('click',()=>{if(busy())return;const entry=draft.referenceMetadataUpdate,status=root.querySelector('[data-completion-status]'),reference=item?.snapshot?.references?.find(row=>row.id===entry.referenceId&&row.confirmed===true);if(!reference){status.textContent='请选择已有文献。';return;}if(reference.citationText){status.textContent='此文献保留原始题录，请先核对原始条目，不能直接覆盖。';return;}if(!referenceTypes.some(([type])=>type===entry.documentType)){status.textContent='请选择支持的文献类型。';return;}if(!validReferenceURL(entry.url)){status.textContent='请输入有效的文献网址（http 或 https）。';return;}const index=draft.referenceMetadataUpdates.findIndex(row=>row.referenceId===entry.referenceId);if(index<0&&draft.referenceMetadataUpdates.length>=30){status.textContent='本次最多更新 30 篇文献。';return;}if(index<0)draft.referenceMetadataUpdates.push({...entry});else draft.referenceMetadataUpdates[index]={...entry};draft.referenceMetadataUpdate={referenceId:'',documentType:'',url:''};change();render();});
 root.querySelectorAll('[data-completion-remove-metadata]').forEach(button=>button.addEventListener('click',()=>{if(busy())return;draft.referenceMetadataUpdates.splice(Number(button.dataset.completionRemoveMetadata),1);change();render();}));
 root.querySelectorAll('[data-completion-fragment]').forEach(input=>input.addEventListener(input.tagName==='SELECT'?'change':'input',()=>{draft.referenceFragment[input.dataset.completionFragment]=input.value;change();}));
 root.querySelector('[data-completion-add-reference-text]')?.addEventListener('click',()=>{if(busy())return;const entry=draft.referenceFragment,status=root.querySelector('[data-completion-status]'),reference=item?.snapshot?.references?.find(row=>row.id===entry.referenceId&&row.confirmed===true);if(!reference||!entry.text.trim()){status.textContent='请选择已有文献并填写作者提供的原文或摘要。';return;}if(draft.referenceTexts.length>=10||draft.referenceTexts.some(row=>row.referenceId===entry.referenceId)){status.textContent='每次可为每篇文献添加一段，本次最多添加 10 篇。';return;}draft.referenceTexts.push({...entry});draft.referenceFragment={referenceId:'',text:''};change();render();});
 root.querySelectorAll('[data-completion-remove-reference-text]').forEach(button=>button.addEventListener('click',()=>{if(busy())return;draft.referenceTexts.splice(Number(button.dataset.completionRemoveReferenceText),1);change();render();}));
 root.querySelector('[data-completion-add-fragment]')?.addEventListener('click',()=>{if(busy())return;const fragment=draft.referenceFragment,status=root.querySelector('[data-completion-status]');if(!fragment.referenceId||!fragment.text.trim()){status.textContent='请选择已有文献并填写正文或摘要片段。';return;}if(draft.referenceFragments.length>=10){status.textContent='本次最多补充 10 个文献片段。';return;}draft.referenceFragments.push({...fragment});draft.referenceFragment={referenceId:'',text:''};change();render();});
 root.querySelectorAll('[data-completion-remove-fragment]').forEach(button=>button.addEventListener('click',()=>{if(busy())return;draft.referenceFragments.splice(Number(button.dataset.completionRemoveFragment),1);change();render();}));
 root.querySelector('[data-completion-add-reference]')?.addEventListener('click',()=>{if(busy())return;const reference=draft.reference,status=root.querySelector('[data-completion-status]');if(!reference.title.trim()||!reference.authors.trim()||!reference.year.trim()||!reference.text.trim()){status.textContent='请填写真实题名、作者、年份和可引用正文。';return;}if(!validReferenceURL(reference.url)){status.textContent='请输入有效的文献网址（http 或 https）。';return;}if(draft.references.length>=30){status.textContent='本次最多补充 30 篇文献。';return;}draft.references.push({...reference});draft.reference={title:'',authors:'',year:'',doi:'',text:''};change();render();});
 for(const [selector,key]of [['[data-completion-remove-material]','materials'],['[data-completion-remove-reference]','references']])root.querySelectorAll(selector).forEach(button=>button.addEventListener('click',()=>{if(busy())return;draft[key].splice(Number(button.getAttribute(selector.slice(1,-1))),1);change();render();}));
 const input=root.querySelector('[data-completion-file]'),load=file=>{if(file&&!busy())void importFile(file,root.querySelector('[data-completion-purpose]').value,root.querySelector('[data-completion-import-status]'));};input?.addEventListener('change',()=>load(input.files?.[0]));
 root.querySelector('[data-completion-stored]')?.addEventListener('click',async()=>{if(!busy()){const {openStoredFilePicker}=await import('./file-picker.mjs');if(root.isConnected)openStoredFilePicker({input,onSelect:load,isCurrent:()=>root.isConnected});}});
 root.querySelector('[data-completion-confirm]')?.addEventListener('click',()=>{if(!busy()&&!draft.dirty)void confirm?.();});
 root.querySelectorAll('[data-completion-view]').forEach(button=>button.addEventListener('click',()=>{if(!busy())viewChapter?.(button.dataset.completionView);}));
 root.querySelector('[data-review-saved]')?.addEventListener('click',()=>{if(!busy()&&!draft.dirty&&!simulationPending(draft))void reviewSaved?.();});
 root.querySelector('[data-completion-prepare]')?.addEventListener('click',()=>void prepare());root.querySelector('[data-completion-start]')?.addEventListener('click',()=>void start());root.querySelector('[data-completion-recheck]')?.addEventListener('click',()=>{if(!draft.dirty)recheck();else root.querySelector('[data-completion-status]').textContent='请先保存补充材料，再由系统完善并检查。';});
}
